        text = X.plain(await X.ask(`你是微博投稿 bot「${nameOf(b.who)}」。规矩：${b.rule || '把投稿匿名发出来，前面加【投稿】'}\n收到的投稿：「${m.t}」\n按规矩把它整理成一条要发的微博（匿名，别透露投稿人）。只写微博正文。`) || '') || '【投稿】' + m.t;
        m.done = 1;
